-- Listening clips (Voscreen-style): students receive the shared listenClips collection.
-- Run once in the Supabase SQL editor.
do $$
declare d text;
begin
  d := pg_get_functiondef('public.load_session_state(text)'::regprocedure);
  d := replace(d,
    $old$'testimonials', coalesce(doc->'testimonials', '[]'::jsonb),$old$,
    $new$'testimonials', coalesce(doc->'testimonials', '[]'::jsonb), 'listenClips', coalesce(doc->'listenClips', '[]'::jsonb),$new$);
  if d !~ 'listenClips' then raise exception 'patch did not apply: load_session_state changed'; end if;
  execute d;
end $$;

-- Finding Nemo clips (Pre 1), added hidden: review them in the admin page, then switch them on.
update public.academy_state set data = jsonb_set(data, '{listenClips}', coalesce(data->'listenClips','[]'::jsonb) || $q$[{"id": "lc-nemo-1", "youtubeId": "UDEGqKJVt9k", "start": 337.5, "end": 420, "title": "Meeting the turtles", "lines": [{"t": 338.0, "text": "Oh, he lives! Hey, dude, what happened?", "say": "oh, he LIVES! hey, DUDE, wuh-HAP-pend?", "note": "‘what happened’ بتتقال بسرعة ‘وَ-هابند’: الـ t بتضعف وبتتوصل بالكلمة اللي بعدها. النبرة على LIVES وDUDE."}, {"t": 341.3, "text": "Oh, I saw the whole thing, dude.", "say": "oh, I SAW the WHOLE thing, DUDE.", "note": "الكلمات المهمة (saw, whole, dude) بتتشدد، وكلمة the بتتقال خفيفة جدًا ‘ذَ’ من غير تركيز."}, {"t": 344.1, "text": "First you were all like, whoa, and", "say": "FIRST-you were all LIKE, WHOA, and", "note": "‘first you’ بتتوصل: الـ t مع الـ y بتطلع شبه ‘فيرستشو’. و‘were’ بتتقال خفيفة ‘وَر’."}, {"t": 347.0, "text": "then we were like, whoa! And then you were like, what are you talking about?", "say": "then we were LIKE, WHOA! and then you were LIKE, wuh-da-ya TALK-in-a-BOUT?", "note": "‘what are you’ بتتقال ‘وَدارْيا’ بسرعة، و‘talking about’ بتتوصل ‘توكينجاباوت’."}, {"t": 353.0, "text": "Taking on the jellies! You caught serious thrill issues, dude.", "say": "TAKE-ing-on the JEL-lies! you CAUGHT SEE-ree-us THRILL ISH-ooz, DUDE.", "note": "‘taking on’ بتتوصل ‘تيكينجأون’: صوت الـ ng بيتوصل بحرف الـ o. و‘caught’ طويلة وتقيلة."}, {"t": 357.6, "text": "Oh, awesome! Oh, my stomach. Hey, no hurling on the shell, dude.", "say": "oh, AW-some! oh, my STOM-ach. hey, no HURL-ing-on-the SHELL, DUDE.", "note": "‘hurling’ = يرجّع (عامية). ‘on the’ بتتوصل ‘أونذَ’. النبرة على no وHURL وSHELL."}, {"t": 363.9, "text": "Okay, just waxed it. So, Mr. Turtle... oh, dude, Mr. Turtle is my", "say": "o-KAY, just WAXT-it. so, MIS-ter TUR-tle... oh dude, MIS-ter TUR-tle is my", "note": "‘waxed it’ بتتوصل ‘واكستِت’: الـ t في waxed بتتوصل بـ it. ‘just waxed’ يعني لسه عامل له واكس ولمّع."}, {"t": 369.0, "text": "father. Name's Crush. Crush? Really? Okay, Crush, listen.", "say": "FA-ther. Name's CRUSH. CRUSH? REAL-ly? o-KAY, CRUSH, LIS-ten.", "note": "‘name’s’ اختصار name is، والـ s بتتوصل بالاسم ‘نيمز كراش’. ‘really?’ بنبرة صاعدة للتعجب."}, {"t": 373.7, "text": "I need to get to the", "say": "I NEED ta GET ta tha", "note": "‘to’ بتتقال ‘تَ’ خفيفة (reduction) مش ‘تو’. وكلمة the كمان ‘ذَ’ خفيفة."}, {"t": 376.0, "text": "East Australian Current. Yeah, you're riding it, dude. Check it out.", "say": "EEST aw-STRAIL-yun CUR-rent. yeah, you're RIDE-ing-it, DUDE. CHECK-it OUT.", "note": "‘riding it’ بتتوصل ‘رايدينجِت’. ‘check it out’ بتتقال كأنها كلمة واحدة ‘تشيكِتاوت’."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:00.000Z"}, {"id": "lc-nemo-2", "youtubeId": "UDEGqKJVt9k", "start": 419.5, "end": 482, "title": "The East Australian Current", "lines": [{"t": 420.0, "text": "You mean the swirling vortex of terror?", "say": "you MEAN the SWIRL-ing VOR-tex of TER-ror?", "note": "‘you mean’ بتتوصل ‘يومين’. ‘of’ بتتقال ‘أف’ خفيفة جدًا. النبرة على mean وswirling وvortex وterror."}, {"t": 422.9, "text": "That's it, dude. Of course it is.", "say": "THAT'S it, DUDE. of COURSE it IS.", "note": "‘of course’ بتتقال ‘أفكورس’. و‘it is’ بتتوصل، وكلمة is الأخيرة بتتشدد لأنها تأكيد."}, {"t": 425.4, "text": "Okay, first find your exit, buddy.", "say": "o-KAY, FIRST FIND your EX-it, BUD-dy.", "note": "‘find your’ بتتوصل ‘فايندْيور’. و‘buddy’ الـ dd بتتنطق خفيفة قريبة من الـ r ‘بَري’ بالأمريكي."}, {"t": 428.0, "text": "Do you have your exit, buddy?", "say": "ja HAV-yer EX-it, BUD-dy?", "note": "‘do you’ بتتقال ‘جَ’ في الكلام السريع. و‘have your’ بتتوصل ‘هافْيَر’."}, {"t": 430.5, "text": "Okay, Squirt, here we'll now give you a rundown on proper exit technique.", "say": "o-KAY, SQUIRT, here we'll now GIVE-ya a RUN-down on PROP-er EX-it tek-NEEK.", "note": "‘give you a’ بتتوصل ‘جيفيا’. ‘rundown’ كلمة واحدة النبرة على RUN. ‘technique’ النبرة على الآخر: tek-NEEK."}, {"t": 450.0, "text": "It's like he's trying to speak to me.", "say": "it's LIKE he's TRY-in' ta SPEAK ta ME.", "note": "‘trying to’ بتتقال ‘تراينتا’ (مدموجة). و‘to’ بتبقى ‘تَ’ خفيفة."}, {"t": 452.2, "text": "You know, you're really cute, but I don't know what you're saying.", "say": "you KNOW, you're REAL-ly CUTE, but i-dun-NO what you're SAY-ing.", "note": "‘I don’t know’ في الكلام السريع بتبقى ‘آيدُنو’ (idunno). النبرة على cute وsaying."}, {"t": 456.2, "text": "Say the first thing again. Okay, gentlemen, go! Go, go, go, go!", "say": "SAY the FIRS-THING a-GAIN. o-KAY, GEN-tle-men, GO! GO, go, go, go!", "note": "‘first thing’ الـ t في first بتختفي: ‘فيرس-ثينج’. ‘gentlemen’ النبرة على GEN."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:01.000Z"}, {"id": "lc-nemo-3", "youtubeId": "UDEGqKJVt9k", "start": 2.5, "end": 93, "title": "Morning at school", "lines": [{"t": 3.0, "text": "Wake up, wake up, come on, please.", "say": "WAKE-up, wake-UP, come ON, PLEASE.", "note": "‘wake up’ فعل مركب (phrasal verb): النبرة على UP. وبتتوصل ‘ويكأب’."}, {"t": 5.9, "text": "Oh, I don't want to go to school.", "say": "oh, I DON'T WAN-na GO ta SCHOOL.", "note": "‘want to’ في الكلام السريع بتبقى ‘wanna’ ‘وانَ’. و‘to’ بتبقى ‘تَ’."}, {"t": 8.8, "text": "Five more minutes. No. Get up, get up.", "say": "FIVE-more MIN-utes. NO. GET-UP, get UP.", "note": "‘five more’ بتتوصل ‘فايفمور’. ‘get up’ بتتوصل ‘جيتأب’ والـ t خفيفة."}, {"t": 12.0, "text": "Time for school. All right, I'm up. It's time for school.", "say": "TIME-for SCHOOL. all RIGHT, I'm UP. it's TIME-for SCHOOL.", "note": "‘time for’ بتتوصل ‘تايمفَر’ و‘for’ خفيفة ‘فَر’. ‘it’s time’ بتتوصل."}, {"t": 23.0, "text": "All right, where's the break? You feel a break sometimes. You can't tell, because fluid is rushing to the area.", "say": "all RIGHT, WHERE'S the BREAK? you FEEL a BREAK SOME-times. you CAN'T TELL, be-CAUSE FLU-id is RUSH-ing to the AR-ea.", "note": "‘can’t tell’ الـ t الأخيرة بتختفي، بنفرّقها عن can tell من قوة النبرة. ‘rushing to the’ بتتوصل."}, {"t": 27.9, "text": "Now, any rushing fluids? Are you woozy?", "say": "NOW, AN-y RUSH-ing FLU-ids? are you WOO-zy?", "note": "‘are you’ بتتقال ‘أريا’ بسرعة. ‘woozy’ = دايخ شوية."}, {"t": 29.6, "text": "How many stripes do I have?", "say": "HOW MAN-y STRIPES do I HAVE?", "note": "‘how many’ بتتوصل ‘هاومِني’. ‘do I’ بتتقال ‘دَآي’ بسرعة."}, {"t": 30.8, "text": "Fine, answer the question. Three. No, see, something's wrong with you.", "say": "FINE, AN-ser the QUES-tion. THREE. NO, SEE, SOME-thing's WRONG with YOU.", "note": "‘answer’ الـ w ساكنة: AN-ser. ‘something’s’ اختصار something is. ‘with you’ بتتوصل."}, {"t": 35.6, "text": "I have one, two, three. That's all I have.", "say": "I HAVE ONE, TWO, THREE. THAT'S ALL-I-HAVE.", "note": "‘that’s all I have’ كلها متوصلة بدون وقفة ‘ذاتسأولآيهاف’."}, {"t": 39.2, "text": "Huh. You're okay. See, he's swimming away.", "say": "HUH. you're o-KAY. SEE, he's SWIM-ming a-WAY.", "note": "‘swimming away’ بتتوصل ‘سويمينجاواي’. ‘away’ النبرة على الثانية: a-WAY."}, {"t": 66.0, "text": "Like upset stomach. Maybe I should try humpback.", "say": "like up-SET STOM-ach. MAY-be-I should TRY HUMP-back.", "note": "‘upset’ النبرة على SET. ‘maybe I’ بتتوصل. ‘humpback’ = حوت أحدب."}, {"t": 68.9, "text": "No, don't try humpback. All right. Whoa, it actually sounds sick. Maybe louder. Huh?", "say": "NO, DON'T try HUMP-back. all RIGHT. WHOA, it AK-shwa-lee SOUNDS SICK. MAY-be LOUD-er. HUH?", "note": "‘actually’ بتتقال تقريبًا ‘أكشُلي’. ‘sounds sick’ صوت الـ s المتكرر بيتوصل من غير وقفة."}, {"t": 74.0, "text": "Don't do that too much. Orca? Didn't it sound a little orca-ish?", "say": "DON'T do that too MUCH. OR-ca? DID-n'-dit SOUND a LID-dle OR-ca-ish?", "note": "‘didn’t it’ بتتوصل ‘ديدنتِت’. ‘a little’ الـ tt بتبقى زي d خفيفة ‘ليدل’. ‘-ish’ يعني ‘شبه’."}, {"t": 78.5, "text": "It doesn't sound orca. It sounds like nothing I've ever heard.", "say": "it DUZ-en SOUND OR-ca. it SOUNDS like NOTH-ing-I've EV-er HEARD.", "note": "‘nothing I’ve’ بتتوصل. ‘heard’ بتتقال ‘هيرد’."}, {"t": 83.0, "text": "Just as well. He might be hungry.", "say": "JUST-as WELL. he MIGHT-be HUN-gry.", "note": "‘just as’ بتتوصل ‘جاستاز’. ‘just as well’ = أحسن كده (تعبير)."}, {"t": 85.7, "text": "Don't worry, whales don't eat clownfish. They eat krill. Oh look, krill!", "say": "DON'T WOR-ry, WHALES-don't EAT CLOWN-fish. they EAT KRILL. oh LOOK, KRILL!", "note": "‘whales don’t’ الـ s بتتوصل ‘ويلزدونت’. ‘krill’ كائنات صغيرة بتاكلها الحيتان."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:02.000Z"}, {"id": "lc-nemo-4", "youtubeId": "UDEGqKJVt9k", "start": 263.5, "end": 338, "title": "The jellyfish game", "lines": [{"t": 264.0, "text": "All right, listen to me. I have an idea. A game.", "say": "all RIGHT, LIS-ten to ME. I-have-an-i-DEA. a GAME.", "note": "‘I have an idea’ كلها متوصلة ‘آيهَفانآيديا’. النبرة على DEE."}, {"t": 266.9, "text": "A game, a game? Yes, I love games! Pick me!", "say": "a GAME, a GAME? YES, I-LOVE-GAMES! PICK ME!", "note": "‘I love games’ بتتوصل ‘آيلَفجيمز’. التعجب بيزوّد النبرة والصوت."}, {"t": 269.5, "text": "All right, here's the game. Whoever can hop the fastest out", "say": "all RIGHT, HERE'S the GAME. WHO-ev-er kun HOP the FAS-test-OUT", "note": "‘can’ هنا خفيفة ‘كن’. ‘fastest out’ الـ t في fastest بتتوصل بـ out ‘فاستيستاوت’."}, {"t": 273.0, "text": "of these jellyfish wins. Okay, rules, rules, rules.", "say": "of-these JEL-ly-fish WINS. o-KAY, RULES, RULES, RULES.", "note": "‘of these’ بتتقال ‘أفذيز’. ‘jellyfish’ النبرة على JEL."}, {"t": 275.8, "text": "Okay, you can't touch the tentacles, only the tops.", "say": "o-KAY, you CAN'T TOUCH the TEN-ta-cles, ON-ly the TOPS.", "note": "النفي بيتعرف من نبرة CAN’T الأقوى. ‘tentacles’ النبرة على TEN."}, {"t": 278.6, "text": "Something about tentacles. We're having fun at the same time.", "say": "SOME-thing a-BOUT TEN-ta-cles. we're HAV-ing FUN at-the-SAME-TIME.", "note": "‘something about’ بتتوصل. ‘at the same time’ كلها متوصلة ‘أتذَسيمتايم’."}, {"t": 296.1, "text": "I can do this. Just be careful.", "say": "I kn DO this. JUST-be CARE-ful.", "note": "‘can’ هنا خفيفة ‘كن’. ‘just be’ بتتوصل ‘جاستبي’."}, {"t": 298.0, "text": "Careful? I don't want to make you cry when I win.", "say": "CARE-ful? I DON'T WAN-na MAKE-ya CRY when I WIN.", "note": "‘make you’ بتتقال ‘ميكْيا’. و‘want to’ بتبقى ‘wanna’."}, {"t": 301.0, "text": "No, I don't think so. Give it up, man. You can't fight evolution. That was built with speed.", "say": "NO, I DON'T THINK SO. GIVE-it-UP, MAN. you CAN'T FIGHT e-vo-LU-tion. that was BUILT with SPEED.", "note": "‘give it up’ بتتوصل ‘جيفِتأب’. ‘I don’t think so’ النبرة على THINK وSO."}, {"t": 310.0, "text": "The question is, Dory, are you hungry?", "say": "the QUES-tion is, DO-ry, are-you HUN-gry?", "note": "‘are you’ بتتقال ‘أريا’ بسرعة."}, {"t": 313.0, "text": "Hungry? Yeah! Because you're about to eat my—", "say": "HUN-gry? YEAH! be-CAUSE you're a-BOUT-ta EAT my—", "note": "‘about to’ بتتقال ‘أباوتَ’: الـ t بتتوصل بـ to."}, {"t": 320.0, "text": "The clownfish is the winner! We did it! Look at us, Dory!", "say": "the CLOWN-fish is the WIN-ner! we DID-it! LOOK-at-US, DO-ry!", "note": "‘look at us’ بتتوصل ‘لوكأتأس’. ‘did it’ بتتوصل ‘ديدِت’."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:03.000Z"}, {"id": "lc-nemo-5", "youtubeId": "UDEGqKJVt9k", "start": 92.5, "end": 179, "title": "Fish are friends", "lines": [{"t": 93.0, "text": "Oh, right. Then the meeting has officially", "say": "oh, RIGHT. THEN the MEET-ing has o-FISH-ly", "note": "‘has officially’ بتتقال ‘هازأفيشلي’. النبرة على FI. ‘right then’ = طيب إذن."}, {"t": 101.0, "text": "come to order. Let us all say the pledge.", "say": "come to OR-der. LET-us all SAY the PLEDGE.", "note": "‘let us’ بتتقال ‘لِتس’. ‘pledge’ = عهد/قسم."}, {"t": 104.2, "text": "I am a nice shark, not a mindless eating machine.", "say": "I-am-a NICE SHARK, NOT-a MIND-less EAT-ing ma-SHEEN.", "note": "‘I am a’ بتتوصل ‘آيمَم’. ‘not a’ بتتوصل ‘ناتَ’. ‘machine’ النبرة على SHEEN."}, {"t": 108.2, "text": "If I am to change this image, I must first change.", "say": "if-I-am-ta CHANGE this IM-ij, I must FIRST CHANGE.", "note": "‘if I am to’ كلمات خفيفة بتتقال بسرعة. ‘image’ ‘إيمِج’."}, {"t": 112.2, "text": "Fish are friends, not food. Except stinking dolphins!", "say": "FISH-are FRIENDS, not FOOD. ex-CEPT STINK-ing DOL-phins!", "note": "‘fish are’ بتتوصل ‘فيشار’. ‘except’ النبرة على CEPT."}, {"t": 117.5, "text": "Dolphins, yeah. They think they're so cute.", "say": "DOL-phins, YEAH. they THINK-they're so CUTE.", "note": "‘think they’re’ الـ k بتتوصل بـ th. تكرار dolphins بنبرة سخرية."}, {"t": 120.2, "text": "Oh look at me, I'ma flip. A little dolphin!", "say": "oh LOOK-at ME, I'ma FLIP. a LID-dle DOL-phin!", "note": "‘I’ma’ اختصار I am going to في العامية. ‘a little’ الـ tt بتبقى d خفيفة."}, {"t": 122.8, "text": "Let me flip for you. Right then. Today's meeting is step five: bring a fish friend.", "say": "LEM-me FLIP for YOU. RIGHT then. to-DAY'S MEET-ing is STEP FIVE: BRING-a FISH FRIEND.", "note": "‘let me’ بتتقال ‘ليمي’ (lemme). ‘bring a’ بتتوصل ‘برينجا’."}, {"t": 127.0, "text": "Now, do you all have your friends?", "say": "NOW, ja ALL have-yer FRIENDS?", "note": "‘do you’ بتتقال ‘جَ’ بسرعة. ‘have your’ بتتوصل."}, {"t": 128.6, "text": "Got mine. Hey there! How about you, chum?", "say": "GOT MINE. HEY there! HOW-a-BOUT-you, CHUM?", "note": "‘how about you’ بتتوصل ‘هاوأباوتيو’. ‘chum’ = يا صاحبي."}, {"t": 133.8, "text": "Oh well, I seem to have misplaced my friend.", "say": "oh WELL, I SEEM-ta-have MIS-placed my FRIEND.", "note": "‘seem to have’ بتتقال ‘سيمتاف’. ‘misplaced’ النبرة على MIS."}, {"t": 140.0, "text": "That's all right, jump. But I'm feeling this would be a difficult step.", "say": "THAT'S-all-RIGHT, JUMP. but I'm FEEL-ing this would be a DIF-i-cult STEP.", "note": "‘that’s all right’ كلها متوصلة. ‘difficult’ غالبًا بتتقال 3 مقاطع DIF-i-cult."}, {"t": 143.8, "text": "You can help yourself to one of my friends.", "say": "you can HELP your-SELF to ONE-of my FRIENDS.", "note": "‘help yourself’ = اتفضل خد براحتك. ‘one of’ بتتوصل ‘وانأف’."}, {"t": 146.1, "text": "Oh, thanks, mate. Hello, my name is Bruce.", "say": "oh, THANKS, MATE. HEL-LO, my NAME-is BRUCE.", "note": "‘mate’ كلمة أسترالية بمعنى صاحبي. ‘name is’ بتتوصل ‘نيمز’."}, {"t": 149.2, "text": "Hello, Bruce. It has been three weeks since my last fish.", "say": "hel-LO, BRUCE. it has BEEN THREE WEEKS since-my LAS-FISH.", "note": "‘since my’ بتتوصل. ‘last fish’ الـ t في last بتختفي ‘لاسفيش’."}, {"t": 155.0, "text": "On my honor, may I be chopped up and made into soup.", "say": "on my HON-or, may I be CHOPT-up and MADE in-ta SOUP.", "note": "‘chopped up’ بتتوصل ‘تشوبتأب’. ‘made into’ بتتوصل ‘ميدينتو’."}, {"t": 158.6, "text": "You're an inspiration to all of us, Bruce.", "say": "you're-an in-spi-RAY-shun ta ALL-of-US, BRUCE.", "note": "‘you’re an’ بتتوصل ‘يورَن’. ‘inspiration’ النبرة على RAY. ‘all of us’ بتتوصل."}, {"t": 161.4, "text": "Right then, who's next? Yes, the little sheila down the front. Come on up here.", "say": "RIGHT then, WHO'S-NEXT? YES, the LID-dle SHEI-la DOWN the FRONT. come-on-UP here.", "note": "‘who’s next’ بتتوصل ‘هوزنكست’. ‘sheila’ كلمة أسترالية = بنت. ‘come on up’ بتتوصل."}, {"t": 168.1, "text": "Hi, I'm Dory. Hi, Dory. Well, I don't think I've ever eaten a fish.", "say": "HI, I'm DO-ry. HI, DO-ry. WELL, I DON'T-THINK-I'VE-EV-er EAT-en a FISH.", "note": "‘I don’t think I’ve ever’ سلسلة متوصلة ‘آيدونتثينكآيفإيفر’. ‘eaten a’ بتتوصل."}, {"t": 174.5, "text": "That's incredible. Good on you, mate.", "say": "THAT'S in-CRED-i-ble. GOOD-on-YOU, MATE.", "note": "‘incredible’ النبرة على CRED. ‘good on you’ عبارة أسترالية = برافو عليك."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:04.000Z"}, {"id": "lc-nemo-6", "youtubeId": "UDEGqKJVt9k", "start": 178.5, "end": 264, "title": "Dory forgets", "lines": [{"t": 179.0, "text": "I'm glad I got that off my chest.", "say": "I'm GLAD I GOT-that-OFF-my CHEST.", "note": "‘got that off my’ بتتوصل. ‘get something off your chest’ = فضفضة وريّحت نفسك."}, {"t": 181.0, "text": "You quit trying to swim here?", "say": "you QUIT TRY-ing to SWIM HERE?", "note": "‘quit trying’ الـ t بتتوصل بـ tr ‘كويتتراينج’. ‘trying to’ بتتقال ‘تراينتا’."}, {"t": 182.7, "text": "What, the ocean's not big enough for you or something? You got a problem?", "say": "WHAT, the O-cean's NOT-BIG-e-NOUGH for YOU or SOME-thing? you GOT-a PROB-lem?", "note": "‘not big enough’ بإيقاع ثابت ‘نات-بيج-إيناف’. ‘you got a’ بتتقال ‘يوجاتا’."}, {"t": 187.0, "text": "Buddy? Huh? Do you, do you, do you want a piece of me?", "say": "BUD-dy? HUH? ja, ja, ja WAN-na PIECE-a ME?", "note": "‘want a’ بتتقال ‘وانا’. ‘piece of me’ تحدّي: عايز تتخانق؟ و‘of’ بتبقى ‘ə’."}, {"t": 190.5, "text": "Yeah, yeah. Oh, I'm scared now!", "say": "YEAH, YEAH. oh, I'm SCARED NOW!", "note": "‘scared now’ بنبرة ساخرة، والـ d بتتوصل بـ n."}, {"t": 192.5, "text": "What? Wait a minute. Stop following me.", "say": "WHAT? WAIT-a-MIN-ute. STOP FOL-low-ing ME.", "note": "‘wait a minute’ كلها متوصلة ‘ويتَمِنِت’. ‘stop following’ الـ p بتتوصل."}, {"t": 195.0, "text": "Okay, what are you talking about?", "say": "o-KAY, wud-er-ya TALK-in-a-BOUT?", "note": "‘what are you’ بتتقال ‘وَدَريا’. ‘talking about’ بتتوصل."}, {"t": 196.9, "text": "You're showing me which way the boat went.", "say": "you're SHOW-ing-me WHICH WAY the BOAT-WENT.", "note": "‘showing me’ بتتوصل. ‘boat went’ الـ t بتتوصل بـ w."}, {"t": 199.2, "text": "A boat? Hey, I've seen a boat that passed by not too long ago.", "say": "a BOAT? HEY, I've SEEN a BOAT that PAST-BY not-too-LONG-a-GO.", "note": "‘passed by’ بتتوصل ‘باستباي’. ‘not too long ago’ بإيقاع واحد."}, {"t": 202.8, "text": "It went, um, this way. It went this way. Follow me.", "say": "it WENT, um, THIS-WAY. it WENT THIS-WAY. FOL-low ME.", "note": "‘um’ تردد. ‘this way’ الـ s بتتوصل ‘ذيسواي’."}, {"t": 205.6, "text": "Wait a minute, wait a minute. What is going on?", "say": "WAIT-a-MIN-ute, wait-a-MIN-ute. WHAT-is-GO-ing-ON?", "note": "‘what is going on’ بتتوصل ‘واتِزجوِينجأون’، جملة شائعة جدًا."}, {"t": 208.2, "text": "You already told me which way the boat was going.", "say": "you al-READ-y TOLD-me WHICH WAY the BOAT was GO-ing.", "note": "‘already’ النبرة على READ. ‘told me’ بتتوصل ‘تولدمي’."}, {"t": 211.0, "text": "Oh no, this is some kind of practical joke.", "say": "oh NO, this is SOME-kind-of PRAC-ti-cal JOKE.", "note": "‘some kind of’ بتتقال ‘سمكايندأف’. ‘practical’ النبرة على PRAC."}, {"t": 214.2, "text": "It's not funny. And I know funny, I'm a clownfish.", "say": "it's NOT FUN-ny. and I KNOW FUN-ny, I'm-a CLOWN-fish.", "note": "‘I’m a’ بتتوصل ‘آيمَ’. وفيها تلاعب: clownfish = مهرّج (funny)."}, {"t": 218.0, "text": "I'm so sorry. See, I suffer from short-term memory loss.", "say": "I'm SO SOR-ry. SEE, I SUF-fer from SHORT-term MEM-o-ry LOSS.", "note": "‘suffer from’ بتتوصل و‘from’ خفيفة ‘فرَم’. ‘short-term’ النبرة على SHORT. ‘memory loss’ = فقدان الذاكرة."}, {"t": 226.0, "text": "It's true. I forget things almost instantly.", "say": "it's TRUE. I for-GET THINGS AL-most IN-stant-ly.", "note": "‘forget things’ الـ t بتتوصل بـ th. ‘almost’ النبرة على AL."}, {"t": 229.0, "text": "It runs in my family. Well, I mean, at least I think it does.", "say": "it RUNZ-in my FAM-i-ly. WELL, I MEAN, at-LEAST-I-THINK-it DUZ.", "note": "‘runs in’ بتتوصل ‘رانزين’. ‘at least I think it’ كلها متوصلة. ‘runs in the family’ = وراثي."}, {"t": 233.1, "text": "Do you know where my dad is?", "say": "ja KNOW where-my DAD is?", "note": "‘do you know’ بتتقال ‘جَنو’ بسرعة. ‘where my’ بتتوصل."}, {"t": 235.0, "text": "Your dad's probably back at the pet store.", "say": "your DAD'S PROB-lee BACK-at-the PET STORE.", "note": "‘probably’ غالبًا بتتقال ‘PROB-lee’ (مقطعين). ‘back at the’ بتتوصل."}, {"t": 242.0, "text": "Pet store? Yeah, you know, like, I'm from Bob's Fishmart.", "say": "PET STORE? YEAH, you KNOW, LIKE, I'm from BOB'S FISH-mart.", "note": "‘pet store’ الـ t في pet بتخفّ، والنبرة على PET. ‘you know’ حشو في الكلام."}, {"t": 246.2, "text": "So which one is it? I'm from the ocean. Ah, the ocean.", "say": "SO which-ONE-is-it? I'm from the O-cean. AH, the O-cean.", "note": "‘which one is it’ بتتوصل ‘ويتشوانيزِت’. ‘from the’ بتتقال ‘فرَمذَ’."}], "levelId": "l8", "active": false, "createdAt": "2026-11-25T17:00:05.000Z"}]$q$::jsonb, true), updated_at = now()
where id = 'academy/main' and not (coalesce(data->'listenClips','[]'::jsonb) @> '[{"id":"lc-nemo-1"}]'::jsonb);
